// Prepare email payload, HTML body, and convert base64 resume attachment to binary
const payload = $input.first()?.json?.body || {};
const attachments = payload.attachments || [];

let binaryData = undefined;
if (Array.isArray(attachments) && attachments.length > 0 && attachments[0]?.content) {
  binaryData = {
    attachment_0: {
      data: attachments[0].content,
      fileName: attachments[0].filename || 'Johnson_Thomas_DevOps_Resume.pdf',
      mimeType: attachments[0].type || 'application/pdf'
    }
  };
}

return [{
  json: {
    to: payload.to,
    subject: payload.subject,
    body: payload.body,
    html: payload.html || payload.body,
    from_name: payload.from_name || 'Johnson Thomas',
    recruiter_name: payload.recruiter_name || 'Hiring Team',
    company: payload.company || '',
    job_title: payload.job_title || '',
    has_attachment: Boolean(binaryData)
  },
  ...(binaryData ? { binary: binaryData } : {})
}];

// Verify dispatch status and format response payload
const result = $input.first()?.json || {};
const inputData = $('Attach Resume Binary').first()?.json || {};

if (result.error) {
  return [{
    json: {
      success: false,
      error: `Failed to send email: ${result.error.message || result.error}`,
      to: inputData.to,
      timestamp: new Date().toISOString()
    }
  }];
}

return [{
  json: {
    success: true,
    message: `Cold outreach email successfully sent to ${inputData.to} via Gmail without attribution!`,
    to: inputData.to,
    subject: inputData.subject,
    has_resume: Boolean(inputData.has_attachment),
    sent_at: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }),
    timestamp: new Date().toISOString()
  }
}];
